mcp:tool-listener.mcp:parameters-schema:
{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
        "productId": {
            "type": "string",
            "description": "SAP product (material) number, for example 30001."
        },
        "lang": {
            "type": "string",
            "description": "Optional two-letter ISO language code, for example FR, DE, ES or ZH.",
            "minLength": 2,
            "maxLength": 2
        }
    },
    "required": [
        "productId"
    ]
}
